const dedupe = (cells: Cell[]): Cell[] => [
  ...new Map(cells.map((cell) => [key(cell), cell])).values(),
];

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const liveKeys = new Set(liveCells.map(key));
  const isLive = (cell: Cell): boolean => liveKeys.has(key(cell));
  const liveNeighbourCount = (cell: Cell): number =>
    neighbours(cell).filter(isLive).length;

  // A cell can only change state if it is live or touches a live cell.
  const candidates = dedupe(liveCells.flatMap((cell) => [cell, ...neighbours(cell)]));

  return candidates.filter((cell) => {
    const count = liveNeighbourCount(cell);
    return count === 3 || (count === 2 && isLive(cell));
  });
}
